#include <iostream>
#include <memory>
#include <vector>

struct Spark
{
    int life;
    Spark(int life) : life(life) {}
};

int main()
{
    std::vector<std::unique_ptr<Spark>> slots(3);   // 3 empty slots

    slots[0] = std::make_unique<Spark>(1);
    slots[2] = std::make_unique<Spark>(3);

    for (int frame = 1; frame <= 3; frame++) {
        for (auto& s : slots) {
            if (!s) continue;                        // free slot
            if (--s->life <= 0) s.reset();           // expired: deleted, slot freed
        }
        int active = 0;
        for (auto& s : slots) if (s) active++;
        std::cout << "frame " << frame << ": " << active << " active\n";
    }
    return 0;
}

