exercises.solution:
#include <memory>
#include <vector>

struct Projectile
{
    inline static int alive = 0;
    double x;
    double speed;
    int life;            // updates left before it expires
    Projectile(double x, double speed, int life) : x(x), speed(speed), life(life) { alive++; }
    ~Projectile() { alive--; }
};

// Rule of zero: the vector of unique_ptrs owns every projectile,
// so the pool needs no destructor and can't leak.
class ProjectilePool
{
public:
    explicit ProjectilePool(int capacity) : slots(capacity > 0 ? capacity : 0) {}

    int spawn(double x, double speed, int life)
    {
        if (life <= 0) return -1;
        for (int i = 0; i < (int)slots.size(); i++) {
            if (!slots[i]) {                        // the lowest free slot
                slots[i] = std::make_unique<Projectile>(x, speed, life);
                return i;
            }
        }
        return -1;                                  // pool is full
    }

    bool despawn(int slot)
    {
        if (!valid(slot) || !slots[slot]) return false;
        slots[slot].reset();                        // deletes the projectile, frees the slot
        return true;
    }

    void update()
    {
        for (auto& p : slots) {
            if (!p) continue;
            p->x += p->speed;
            p->life--;
            if (p->life <= 0) p.reset();            // expired
        }
    }

    int active() const
    {
        int n = 0;
        for (const auto& p : slots) if (p) n++;
        return n;
    }
    int capacity() const { return slots.size(); }
    double positionOf(int slot) const
    {
        if (!valid(slot) || !slots[slot]) return -1;
        return slots[slot]->x;
    }
private:
    bool valid(int slot) const { return slot >= 0 && slot < (int)slots.size(); }
    std::vector<std::unique_ptr<Projectile>> slots;   // an empty unique_ptr = a free slot
};

