exercises.solution:
#include <algorithm>
#include <cmath>
#include <memory>
#include <string>
#include <vector>

struct Enemy
{
    inline static int alive = 0;
    std::string name;
    double x;
    int hp;
    Enemy(std::string name, double x, int hp) : name(name), x(x), hp(hp) { alive++; }
    ~Enemy() { alive--; }
};

struct Shot
{
    inline static int alive = 0;
    double x;
    std::weak_ptr<Enemy> target;    // a shot follows an enemy but never keeps it alive
    Shot(double x, std::weak_ptr<Enemy> target) : x(x), target(target) { alive++; }
    ~Shot() { alive--; }
};

class Battle
{
public:
    std::shared_ptr<Enemy> addEnemy(const std::string& name, double x, int hp)
    {
        auto e = std::make_shared<Enemy>(name, x, hp);
        enemies.push_back(e);
        return e;
    }
    int enemiesLeft() const { return enemies.size(); }

    void fire(double fromX, const std::shared_ptr<Enemy>& target)
    {
        if (!target) return;
        shots.push_back(std::make_unique<Shot>(fromX, target));
    }

    void removeEnemy(const std::string& name)
    {
        for (size_t i = 0; i < enemies.size(); i++) {
            if (enemies[i]->name == name) {
                enemies.erase(enemies.begin() + i);   // the battle lets go of it
                return;
            }
        }
    }

    void update()
    {
        // 1. move every shot; remove the ones that hit or lost their target
        for (size_t i = 0; i < shots.size(); ) {
            Shot& s = *shots[i];
            auto e = s.target.lock();
            bool done = false;
            if (!e) {
                done = true;                           // target gone: the shot fizzles
            } else if (std::fabs(e->x - s.x) <= Speed) {
                e->hp -= Damage;                       // hit
                done = true;
            } else {
                s.x += (e->x > s.x) ? Speed : -Speed;  // fly toward it
            }
            if (done) shots.erase(shots.begin() + i);  // deletes the Shot
            else i++;
        }
        // 2. drop enemies with no health left
        enemies.erase(std::remove_if(enemies.begin(), enemies.end(),
                                     [](const std::shared_ptr<Enemy>& e) { return e->hp <= 0; }),
                      enemies.end());
    }

    int shotsInFlight() const { return shots.size(); }
private:
    static constexpr double Speed = 5;
    static constexpr int Damage = 10;
    std::vector<std::shared_ptr<Enemy>> enemies;   // the battle owns the enemies (others may too)
    std::vector<std::unique_ptr<Shot>> shots;      // the battle alone owns the shots
};
